import * as React from 'react';

export type InputDensity = 'comfortable' | 'compact';

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label: string;
  hint?: string;
  error?: string;
  density?: InputDensity;
  fieldClassName?: string;
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(function Input(
  {
    id,
    label,
    hint,
    error,
    density = 'comfortable',
    className = '',
    fieldClassName = '',
    'aria-describedby': userDescribedBy,
    'aria-invalid': userAriaInvalid,
    ...rest
  },
  ref,
) {
  const autoId = React.useId();
  const inputId = id || `f12-input-${autoId.replace(/:/g, '')}`;
  const hintId = hint ? `${inputId}-hint` : undefined;
  const errorId = error ? `${inputId}-error` : undefined;
  const describedBy =
    [userDescribedBy, hintId, errorId].filter(Boolean).join(' ') || undefined;
  const isCompact = density === 'compact';

  return (
    <div
      className={`f12-field${isCompact ? ' f12-field-compact' : ''}${fieldClassName ? ` ${fieldClassName}` : ''}`}
      data-density={isCompact ? 'compact' : undefined}
    >
      <label htmlFor={inputId} className="f12-label">
        {label}
      </label>
      <input
        ref={ref}
        id={inputId}
        className={`f12-input${isCompact ? ' f12-input-compact' : ''}${className ? ` ${className}` : ''}`}
        aria-describedby={describedBy}
        aria-invalid={error ? true : userAriaInvalid}
        {...rest}
      />
      {hint && (
        <p id={hintId} className="f12-hint">
          {hint}
        </p>
      )}
      {error && (
        <p id={errorId} className="f12-error" role="alert">
          <span className="f12-error-flag" aria-hidden="true">
            !
          </span>
          <span>{error}</span>
        </p>
      )}
    </div>
  );
});

'use client';

import * as React from 'react';

export type BadgeStatus = 'neutral' | 'info' | 'success' | 'warning' | 'danger';

const BADGE_STATUS_GLYPHS: Record<BadgeStatus, string | undefined> = {
  neutral: undefined,
  info: '[i]',
  success: '[✓]',
  warning: '[!]',
  danger: '[×]',
};

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  status?: BadgeStatus;
  glyph?: string | false;
  pop?: boolean;
  burst?: boolean;
  children?: React.ReactNode;
}

export function Burst() {
  const lines: React.ReactElement[] = [];
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2;
    const r1 = 15 + (i % 2) * 3;
    const r2 = 25 + (i % 3) * 3;
    lines.push(
      <line
        key={i}
        x1={30 + Math.cos(a) * r1 * 1.9}
        y1={14 + Math.sin(a) * r1 * 0.75}
        x2={30 + Math.cos(a) * r2 * 1.9}
        y2={14 + Math.sin(a) * r2 * 0.75}
      />,
    );
  }
  return (
    <svg className="f12-burst" viewBox="-20 -12 100 52" aria-hidden="true">
      {lines}
    </svg>
  );
}

export const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(function Badge(
  { status, glyph, pop = false, burst, className = '', children, ...rest },
  ref,
) {
  const showBurst = burst ?? status === undefined;
  const statusClass = status ? ` f12-status-${status}` : '';
  const resolvedGlyph =
    glyph === false
      ? undefined
      : glyph !== undefined
        ? glyph
        : status
          ? BADGE_STATUS_GLYPHS[status]
          : undefined;

  return (
    <span
      ref={ref}
      className={`f12-badge${statusClass}${pop ? ' f12-pop pop' : ''}${className ? ` ${className}` : ''}`}
      data-status={status}
      {...rest}
    >
      {showBurst && <Burst />}
      <span className="f12-badge-t">
        {resolvedGlyph && (
          <span className="f12-status-glyph" aria-hidden="true">
            {resolvedGlyph}
          </span>
        )}
        {children}
      </span>
    </span>
  );
});

